/**
 * Generates the profile banners with the existing public GitHub portrait.
 * Dependencies: Node.js built-ins only. Documentation: DOCUMENTACAO.md.
 * Edit renderBanner for copy, palette and motion. No network or credentials.
 */
import { writeFileSync } from 'node:fs';
const portrait = "<image x=\"70\" y=\"130\" width=\"310\" height=\"330\" preserveAspectRatio=\"xMidYMid slice\" href=\"data:image/png;base64,\"/>";
function renderBanner(portrait,light=false){
const p={bg:"#05080D",ink:"#F8FAFC",muted:"#CBD5E1",line:"#263746",a:"#55DDE0",b:"#7AE2C3"};
const chips=[["PYTHON","01",48,0],["JAVA · SQL","02",223,.15],["ML · ANALYTICS","03",430,.3]];
return `<!-- Profile banner. Source: scripts/generate_profile_banner.mjs. Documentation: DOCUMENTACAO.md. -->
<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="440" viewBox="0 0 1000 440" role="img" aria-labelledby="title desc">
<title id="title">Walteir Junior — Inteligência Artificial e Ciência de Dados</title>
<desc id="desc">Retrato fotográfico com movimento suave. Python, Java, SQL, Machine Learning e Analytics. Graduando, construindo projetos com dados e automação.</desc>
<defs><clipPath id="portraitClip"><circle cx="799" cy="198" r="125"/></clipPath></defs>
<style>
text{font-family:Arial,Helvetica,sans-serif}
.mono{font-family:Consolas,monospace;letter-spacing:2px}
.drift{animation:drift 7s ease-in-out infinite;transform-origin:799px 198px}
.orbit{animation:orbit 28s linear infinite;transform-origin:799px 198px}
.chip{animation:reveal .9s ease-out both}
@keyframes drift{50%{transform:translateY(-5px)}}
@keyframes orbit{to{transform:rotate(360deg)}}
@keyframes reveal{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){.drift,.orbit,.chip{animation:none}}
</style>
<rect width="1000" height="440" rx="20" fill="${p.bg}"/>
<path d="M48 52H952M48 336H952" stroke="${p.line}"/>
<text x="48" y="34" class="mono" font-size="12" fill="${p.muted}">WJR007 / PORTFÓLIO</text>
<text x="952" y="34" text-anchor="end" class="mono" font-size="12" fill="${p.a}">IA · DADOS · SOFTWARE</text>
<text x="48" y="109" class="mono" font-size="13" fill="${p.a}">INTELIGÊNCIA ARTIFICIAL &amp; CIÊNCIA DE DADOS</text>
<text x="44" y="178" font-size="59" font-weight="700" letter-spacing="-2" fill="${p.ink}">Walteir Junior.</text>
<text x="48" y="222" font-size="22" fill="${p.muted}">Dados, código e ideias em prática.</text>
<text x="48" y="273" font-size="16" fill="${p.muted}">Graduando · Machine Learning · Automação</text>
<path d="M48 298h66" stroke="${p.b}" stroke-width="3"/>
<circle cx="799" cy="198" r="141" fill="none" stroke="${p.line}"/>
<g class="orbit"><circle cx="799" cy="198" r="141" fill="none" stroke="${p.a}" stroke-dasharray="90 796" stroke-width="2"/><circle cx="940" cy="198" r="4" fill="${p.b}"/></g>
<g clip-path="url(#portraitClip)"><g class="drift"><g transform="translate(612 -40) scale(.83)" fill="${p.a}">${portrait}</g></g></g>
${chips.map(([label,n,x,delay])=>`<g class="chip" style="animation-delay:${delay}s"><text x="${x}" y="372" class="mono" font-size="11" fill="${p.muted}">${n} / STACK</text><text x="${x}" y="406" font-size="19" font-weight="600" fill="${p.ink}">${label}</text></g>`).join("\n")}
<text x="952" y="374" text-anchor="end" font-size="12" fill="${p.muted}">APRENDER. CONSTRUIR.</text>
<text x="952" y="402" text-anchor="end" font-size="18" fill="${p.b}">Compartilhar a evolução.</text>
</svg>\n`;
}
for (const light of [false,true]) {
  writeFileSync(new URL(light ? '../light.svg' : '../dark.svg', import.meta.url), renderBanner(portrait,light));
}
